<!doctype html><html><head><meta charset="utf-8"><title><?php echo e($advertisement->job_title); ?></title><style>body{font-family:Arial,sans-serif;color:#333;margin:0}.wrap{max-width:800px;margin:0 auto}.hero{background:linear-gradient(135deg,#667eea,#764ba2);color:#fff;padding:40px 30px;text-align:center}.hero h1{margin:0 0 10px;font-size:32px}.meta{background:#f8f9fa;padding:20px;margin:20px 0;display:grid;grid-template-columns:1fr 1fr;gap:20px}.meta small{display:block;color:#666;text-transform:uppercase}.section{margin:28px 0}.section h2{color:#667eea;border-bottom:3px solid #667eea;padding-bottom:10px}.apply{background:linear-gradient(135deg,#667eea,#764ba2);color:#fff;padding:25px;text-align:center;border-radius:8px}@media print{.hero,.apply{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><div class="wrap"><div class="hero"><h1><?php echo e($advertisement->job_title); ?></h1><div><?php echo e($advertisement->company_name ?? ''); ?></div></div><div class="meta"><div><small>Category</small><b><?php echo e($advertisement->category); ?></b></div><div><small>Location</small><b><?php echo e($advertisement->location); ?></b></div><div><small>Employment Type</small><b><?php echo e($advertisement->type); ?></b></div><?php if($advertisement->salary): ?><div><small>Salary Range</small><b><?php echo e($advertisement->salary); ?></b></div><?php endif; ?></div><div class="section"><h2>Job Description</h2><div><?php echo nl2br(e($advertisement->description)); ?></div></div><div class="section"><h2>Requirements &amp; Qualifications</h2><div><?php echo nl2br(e($advertisement->requirements)); ?></div></div><div class="apply"><h3>How to Apply</h3><div><?php echo e($advertisement->contact_email); ?></div><?php if($advertisement->contact_phone): ?><div><?php echo e($advertisement->contact_phone); ?></div><?php endif; ?><p>Apply Before: <?php echo e($advertisement->deadline?->format('F d, Y')); ?></p></div></div></body></html>
